"""K49 uniqueness for all k (r1, C046).
Lean 4 core (SHA-pinned; contains the reviewed K58/K59/K60 developments verbatim plus new code/shape lemmas):
  unique_sep: for every k>=1, every guarded O in p,q of AST size k+5 that separates F_k=box^k p and F_(k+1)
  (different eventual outcome pair) is syntactically S_k = box(~q | box^k F) or box(box^k F | ~q).
  sk_codes: S_k code 0 (all cooperate) vs F_k, code 2 (DD) vs F_(k+1).
Four mutated statements (single-order conclusion, box^(k+1), ~p instead of ~q, wrong S_k code) must each fail.
Python: independent literal evaluator (height semantics, K40 horizon) checks S_k cells for k<=10 and brute-forces
ALL syntactic guarded formulas of size 6 and 7 (no reduction): exactly the two S_1 / S_2 orders separate.
Run: python -I c046_fk_unique.py (needs lean on PATH; one Lean process, ~30 s, ~3 GB).
"""
import base64, zlib, hashlib, subprocess, re, time
MAIN = zlib.decompress(base64.b64decode("")).decode()
assert hashlib.sha256(MAIN.encode()).hexdigest() == "f04503e30b403f1b2cbaa37e924c7133e01b653974ba792558c455a0699be77f"
MUTS = zlib.decompress(base64.b64decode("")).decode()

def run_lean():
    full = MAIN + '\n\n' + MUTS + '\n'
    nmain = MAIN.count('\n') + 1
    r = subprocess.run(['lean', '--stdin'], input=full, capture_output=True, text=True, timeout=110)
    out = r.stdout + r.stderr
    errs = [int(m.group(1)) for m in re.finditer(r'<stdin>:(\d+):\d+: error', out)]
    assert 'sorryAx' not in out and 'ofReduceBool' not in out
    for name in ['size_bound', 'code_same', 'shapeA', 'shapeB', 'shapeC', 'unique_sep', 'sk_codes']:
        assert re.search(r"'%s' depends on axioms" % name, out), name
    assert all(e > nmain for e in errs), ('error in main development', errs[:5], out[:2000])
    # each mutation block must produce at least one error inside its line range
    lines = full.split('\n')
    starts = [i + 1 for i, l in enumerate(lines) if l.startswith('theorem mut_')]
    assert len(starts) == 4
    bounds = starts + [len(lines) + 1]
    for i in range(4):
        assert any(bounds[i] <= e < bounds[i + 1] for e in errs), ('mutation not rejected', lines[starts[i] - 1])
    return len(errs)

# ---- independent literal evaluator: games O vs F_j = box^j p in height semantics ----
# formula: ('F',),('p',),('q',),('~',a),('&',a,b),('|',a,b),('B',a)
def ev(f, P, Q, h, memo):
    key = (id(f), h)
    if key in memo: return memo[key]
    t = f[0]
    if t == 'F': v = False
    elif t == 'p': v = P[h]
    elif t == 'q': v = Q[h]
    elif t == '~': v = not ev(f[1], P, Q, h, memo)
    elif t == '&': v = ev(f[1], P, Q, h, memo) and ev(f[2], P, Q, h, memo)
    elif t == '|': v = ev(f[1], P, Q, h, memo) or ev(f[2], P, Q, h, memo)
    else: v = all(ev(f[1], P, Q, g, memo) for g in range(h))
    memo[key] = v; return v

def nbox(f): return (f[0] == 'B') + sum(nbox(c) for c in f[1:])

def game(O, j):
    H = 2 * (nbox(O) + j) + 2          # K40 horizon (inclusive) plus slack
    P, Q = [], [h < j for h in range(H + 1)]   # q = F_j vs DefectBot
    o, fv = [], []
    for h in range(H + 1):
        fv.append(all(o[g] for g in range(h - j + 1)) if h >= j else True)
        P.append(fv[h])
        o.append(ev(O, P, Q, h, {}))
    return (o[H], fv[H])

def boxes(k, a):
    for _ in range(k): a = ('B', a)
    return a

def size(f): return 1 + sum(size(c) for c in f[1:])
def guarded(f):
    t = f[0]
    if t in 'pq': return False
    if t in 'FB': return True
    return all(guarded(c) for c in f[1:])

def allf(n, memo={}):
    if n in memo: return memo[n]
    res = []
    if n == 1: res = [('F',), ('p',), ('q',)]
    else:
        res += [('~', a) for a in allf(n - 1)] + [('B', a) for a in allf(n - 1)]
        for i in range(1, n - 1):
            for a in allf(i):
                for b in allf(n - 1 - i):
                    res.append(('&', a, b)); res.append(('|', a, b))
    memo[n] = res; return res

def main():
    t0 = time.time()
    nerr = run_lean()
    t1 = time.time()
    # S_k and its swapped form separate F_k (CC) / F_{k+1} (DD), k=1..10
    for k in range(1, 11):
        for S in (('B', ('|', ('~', ('q',)), boxes(k, ('F',)))), ('B', ('|', boxes(k, ('F',)), ('~', ('q',))))):
            assert size(S) == k + 5
            assert game(S, k) == (True, True) and game(S, k + 1) == (False, False), k
    # brute force over ALL syntactic guarded formulas of size k+5 (no reduction), k=1,2
    found = {}
    for k in (1, 2):
        sk = {('B', ('|', ('~', ('q',)), boxes(k, ('F',)))), ('B', ('|', boxes(k, ('F',)), ('~', ('q',))))}
        seps = set(); n = 0
        for O in allf(k + 5):
            if not guarded(O): continue
            n += 1
            if game(O, k) != game(O, k + 1): seps.add(O)
        assert seps == sk, (k, len(seps))
        found[k] = n
    print('PASS: Lean unique_sep (all k>=1), %d mutation errors located, %.1fs; literal S_k k<=10; '
          'exhaustive syntax size 6/7: %d/%d guarded formulas, only S_1/S_2 (both orders) separate; total %.1fs'
          % (nerr, t1 - t0, found[1], found[2], time.time() - t0))

main()
